class BlockTable:
    """Maps logical token positions to fixed-size physical cache blocks."""

    def __init__(self, block_size: int = 16):
        self.block_size = block_size
        self.blocks: list[int] = []

    def block_for(self, position: int) -> tuple[int, int]:
        idx, offset = divmod(position, self.block_size)
        return self.blocks[idx], offset

    def append_block(self, physical_id: int) -> None:
        self.blocks.append(physical_id)

pub struct RingBuffer<T> {
    items: Vec<Option<T>>,
    head: usize,
    len: usize,
}

impl<T> RingBuffer<T> {
    pub fn with_capacity(cap: usize) -> Self {
        Self { items: (0..cap).map(|_| None).collect(), head: 0, len: 0 }
    }

    pub fn push(&mut self, item: T) {
        let tail = (self.head + self.len) % self.items.len();
        self.items[tail] = Some(item);
        if self.len == self.items.len() { self.head = (self.head + 1) % self.items.len(); } else { self.len += 1; }
    }
}

-- Per-replica serving telemetry, partitioned by day for retention pruning.
CREATE TABLE inference_metrics (
    ts          TIMESTAMPTZ NOT NULL,
    replica_id  TEXT        NOT NULL,
    ttft_ms     DOUBLE PRECISION,
    tpot_ms     DOUBLE PRECISION,
    kv_pages_in_use BIGINT,
    prefix_cache_hit_rate DOUBLE PRECISION
) PARTITION BY RANGE (ts);

CREATE INDEX ON inference_metrics (replica_id, ts DESC);
